#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_MSG_SIZE 1024
#define MSG_TYPE_DATA 0x01
#define MSG_TYPE_ACK  0x02
#define MSG_TYPE_RESET 0x03
#define MSG_TYPE_FIRMWARE 0x04

typedef struct {
    uint8_t msg_type;
    uint16_t payload_len;
    char *payload;
    int ref_count;
    int processed;
} mqtt_message_t;

typedef struct {
    mqtt_message_t *current_msg;
    pthread_mutex_t lock;
    int session_active;
    char device_id[64];
    char *telemetry_buffer;
} device_context_t;

static device_context_t g_ctx;

void init_device_context(const char *dev_id) {
    memset(&g_ctx, 0, sizeof(device_context_t));
    pthread_mutex_init(&g_ctx.lock, NULL);
    strncpy(g_ctx.device_id, dev_id, 63);
    g_ctx.session_active = 1;
    g_ctx.telemetry_buffer = (char *)malloc(4096);
}

mqtt_message_t *allocate_message(uint8_t type, const char *data, uint16_t len) {
    mqtt_message_t *msg = (mqtt_message_t *)malloc(sizeof(mqtt_message_t));
    if (!msg) return NULL;
    msg->msg_type = type;
    msg->payload_len = len;
    msg->payload = (char *)malloc(len + 1);
    if (!msg->payload) { free(msg); return NULL; }
    memcpy(msg->payload, data, len);
    msg->payload[len] = '\0';
    msg->ref_count = 1;
    msg->processed = 0;
    return msg;
}

void release_message(mqtt_message_t *msg) {
    if (msg) {
        if (msg->payload) {
            free(msg->payload);
            msg->payload = NULL;
        }
        free(msg);
    }
}

/* Process incoming MQTT message - handles device telemetry and commands */
int handle_message(const char *raw_data, uint16_t raw_len) {
    if (raw_len < 3) return -1;

    uint8_t type = (uint8_t)raw_data[0];
    uint16_t plen = *(uint16_t *)(raw_data + 1);

    if (plen > MAX_MSG_SIZE || plen > raw_len - 3) return -1;

    mqtt_message_t *msg = allocate_message(type, raw_data + 3, plen);
    if (!msg) return -1;

    pthread_mutex_lock(&g_ctx.lock);

    /* Store reference for async processing */
    if (g_ctx.current_msg != NULL && g_ctx.current_msg->processed) {
        release_message(g_ctx.current_msg);
    }
    g_ctx.current_msg = msg;

    pthread_mutex_unlock(&g_ctx.lock);

    /* Process based on type */
    if (type == MSG_TYPE_RESET) {
        /* Reset handler - cleans up current state */
        pthread_mutex_lock(&g_ctx.lock);
        if (g_ctx.current_msg) {
            release_message(g_ctx.current_msg);
            /* BUG: g_ctx.current_msg not set to NULL here */
        }
        g_ctx.session_active = 0;
        pthread_mutex_unlock(&g_ctx.lock);

        /* Re-initialize session triggers second free via cleanup path */
        g_ctx.session_active = 1;
    }

    if (type == MSG_TYPE_FIRMWARE) {
        /* Firmware update path - attacker controlled payload written to heap */
        pthread_mutex_lock(&g_ctx.lock);
        if (g_ctx.current_msg && g_ctx.current_msg->payload) {
            /* Copy firmware chunk to telemetry buffer for "validation" */
            memcpy(g_ctx.telemetry_buffer, g_ctx.current_msg->payload,
                   g_ctx.current_msg->payload_len);
        }
        /* Double-free: current_msg was already freed in RESET path above
           if a RESET was processed in a concurrent thread */
        release_message(g_ctx.current_msg);
        g_ctx.current_msg = NULL;
        pthread_mutex_unlock(&g_ctx.lock);
    }

    return 0;
}

/* Periodic cleanup called by watchdog timer */
void periodic_cleanup(void) {
    pthread_mutex_lock(&g_ctx.lock);
    if (g_ctx.current_msg && g_ctx.current_msg->processed) {
        release_message(g_ctx.current_msg);
        g_ctx.current_msg = NULL;
    }
    pthread_mutex_unlock(&g_ctx.lock);
}

int main(int argc, char **argv) {
    init_device_context("sensor-node-0x4A");

    /* Main MQTT receive loop would go here */
    /* Simulated: read from stdin for testing */
    char buf[2048];
    while (g_ctx.session_active) {
        int n = read(0, buf, sizeof(buf));
        if (n <= 0) break;
        handle_message(buf, (uint16_t)n);
    }

    free(g_ctx.telemetry_buffer);
    return 0;
}
